// Resolve pulls a pinned WebAssembly component from an OCI registry.
func Resolve(scheme string, spec string) witTypes.Result[ohrats_rc_plugin_package_source.PackageArtifact, string] {
	if scheme != "oci" {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](
			fmt.Sprintf("OCI source does not handle %q", scheme))
	}
	parsed, err := ocisource.ParseSpec(spec)
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	artifact, err := ocisource.Pull(parsed)
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	return witTypes.Ok[ohrats_rc_plugin_package_source.PackageArtifact, string](artifact)
}
